import json, hashlib, re
from pathlib import Path

base=Path('artifacts/review-integrale-2026-10-02'); lp=base/'VOL-12-ledger.json'
d=json.loads(lp.read_text(encoding='utf-8')); chap={}
for f in d['files']:
 p=Path(f['path']); key=p.parts[3].split('-')[1].upper()+'/'+p.name[:2]; chap[key]=f;f['findings']=[]
rows=[]
def add(key,line,cat,sev,problem,proposal):
 f=chap[key]; lines=Path(f['path']).read_text(encoding='utf8').splitlines(); fid=f'V12-{len(rows)+1:02d}'
 rows.append(dict(id=fid,key=key,path=f['path'],line=line,category=cat,severity=sev,problem=problem,proposal=proposal,excerpt=lines[line-1][:180]));f['findings'].append(fid)

add('SP01/01',41,'Completezza','Medio','La mappa presenta tre corpi e due binari senza una tavola concreta dei ruoli e delle procedure esemplificate.','Aggiungere confronto agenti/carabinieri/finanzieri e vice ispettori/marescialli: amministrazione, qualifica iniziale, titolo, fasi, bando campione e data. Rinvio espresso a M-FL04 per la polizia locale.')
add('SP01/02',29,'Normativa e quiz','Grave','Il limite di 29 anni non compiuti viene generalizzato alla famiglia e riproposto nel quiz 2, benché i bandi CC e GdF della stessa documentazione prevedano limiti diversi per ruolo/categoria.','Eliminare la regola unitaria; riportare una tabella per bando, ruolo e contingente con elevazioni. Trasformare quiz 2 in lettura di un bando identificato. La pagina PdS è risultata non accessibile: non sostituire arbitrariamente il suo limite con 26.')
add('SP01/02',29,'Normativa','Grave','Condotta e art.26 L.53/1989 sono ricondotti a una valutazione sempre individuale, escludendo in generale automatismi. La sentenza 40/2024 non abroga tutte le cause automatiche.','Distinguere requisito generale di condotta e cause speciali di esclusione; limitare la pronuncia GdF al vizio di ebbrezza dichiarato illegittimo. Correggere corpo, riepilogo, quiz 4 e source ordinamentale. E01.')
add('SP01/02',29,'Normativa','Grave','Il D.M.198/2003 viene usato come disciplina comune ai tre corpi, anche nel quiz 5.','Esplicitare ambito Polizia di Stato; ricostruire separatamente fonti CC/GdF. Conservare la precisazione già corretta in SP01/04 e SP01/09. Non sostenere nella source che il decreto residui soltanto per requisiti psichici: elimina le stature superate, non gli altri requisiti fisici.')
add('SP01/03',45,'Coerenza e didattica','Medio','Banca dati, quiz, preselezione, componimento e tema sono trattati come formati incompatibili sullo stesso piano. Funzione selettiva, modalità e origine dei quesiti sono assi differenti.','Separare funzione, formato, materiali e tempi; mostrare un esempio CC e uno GdF prima di prescrivere preparazioni diverse. Aggiungere mini elaborato/scaletta commentata, non soltanto rinvii al bando.')
add('SP01/04',64,'Perimetro e apparati','Medio','Il terzo binario dell’allegato GdF resta opaco; la source usa il bando 69 ufficiali, escluso dal perimetro del modulo. Il quiz 4 interroga questo metadato.','Usare protocolli di un bando GdF base/ispettivo pertinente; inserire confronto obbligatoria/facoltativa, esclusione/punteggio, certificazione. Sostituire il quiz sul terzo binario con un caso procedurale pertinente.')
add('SP01/05',158,'Caso e cronologia','Grave','Luca ha già superato prove e corregge la domanda per valorizzare titoli, senza una norma che permetta integrazioni tardive.','Spostare il caso prima della scadenza oppure indicare esatta facoltà e termine d’integrazione. Distinguere possesso, dichiarazione e documentazione come obblighi cumulabili, non alternativi.')
add('SP01/05',142,'Accuratezza','Medio','L’inglese è qualificato più competitivo senza un sistema di punteggio o un confronto che lo dimostri.','Descrivere vantaggi solo in rapporto alle regole della prova e al livello del candidato; eliminare la graduatoria implicita delle lingue.')
add('SP01/06',98,'Completezza e rinvii','Medio','Il capitolo rinvia a penale, procedura e TULPS nel modulo, ma offre quasi soltanto orientamento; CC/GdF ricevono scarso ordinamento di base.','Dichiarare il limite strategico, aggiungere mappa essenziale di funzioni/fonti per i tre corpi e destinazioni precise per lo studio. Non occorre un trattato di penale. Nel caso di autorizzazione irregolare distinguere sanzione amministrativa e reato secondo la norma applicabile.')
add('SP01/07',78,'Procedura e completezza','Grave','Il Decoder non mette in evidenza la scadenza della domanda e invita ad attendere il calendario per la decisione. Può far confondere candidatura e investimento nello studio.','Inserire scadenza, ora, canale, pagamento, ricevuta e facoltà di reinvio; distinguere iscrizione tempestiva e pianificazione successiva. Fornire un Decoder integralmente compilato su un bando campione.')
add('SP01/07',113,'Chiarezza e tabelle','Medio','Non pubblicato viene usato anche dove il dato potrebbe essere soltanto non reperito. La colonna GdF mescola dato comparativo e azione.','Distinguere non previsto, non ancora pubblicato, non reperito e da verificare; considerare anche norme richiamate. Ricostruire tabelle con una riga per procedimento e colonne omogenee.')
add('SP01/08',27,'Promessa e didattica','Medio','Il titolo promette 30/60/90, ma viene sviluppato un ciclo di 90 giorni senza varianti operative a 30 e 60. Il doppio binario alterna due significati.','Fornire tre piani con ipotesi di ore e livello oppure restringere il titolo; aggiungere esempio banca 5000 quesiti/33 giorni con recupero. Riservare doppio binario a base/ispettivo e nominare diversamente teoria/fasi.')
add('SP01/08',270,'Quiz','Medio','I sei quiz sono forniti con chiavi ma senza spiegazioni, pur essendo presentati come ragionati.','Aggiungere motivazione della chiave e spiegazioni specifiche dei distrattori.')
add('SP01/09',32,'Didattica e ridondanza','Medio','I casi ripetono controlla il bando senza dati sufficienti per una soluzione verificabile; sette chiavi su otto sono B, sei consecutive.','Sostituire ripetizioni con casi chiusi: certificato in scadenza, termine domanda, avviso modificato, punteggio e scelta. Variare posizione delle chiavi e plausibilità dei distrattori dopo aver stabilizzato le soluzioni.')
add('SP01/10',174,'Logica del workbook','Medio','Manca lo stato non applicabile; rosso confonde inammissibilità e preparazione insufficiente. La ricevuta è richiesta per decidere se inviare la domanda.','Separare verifica giuridica, stato d’invio e prontezza; introdurre N/A per prove non previste e distinguere checklist prima/dopo l’invio. Raccordare quiz 4 e colori al nuovo criterio.')
add('SP02/01',99,'Normativa dei ruoli','Grave','Il D.M.49/2022 sul ruolo tecnico-scientifico è richiamato per l’ispettore antincendi, confondendo ruoli diversi.','Separare ispettore antincendi e ispettore tecnico-scientifico; allineare fonte e tabella al capitolo 05, che già distingue correttamente i ruoli.')
add('SP02/02',155,'Requisiti e quiz','Grave','Dal solo visus naturale di 12/10 si deduce accessibilità degli altri ruoli e preclusione assoluta permanente a vigile. Il quiz 5 non contiene una risposta pienamente valida.','Sostituire la chiave con dati insufficienti per giudicare l’idoneità complessiva; distinguere accertamento attuale, correzione consentita e ulteriori parametri previsti dal D.M.166/2019. Eliminare autodiagnosi e prognosi definitive. E03.')
add('SP02/02',131,'Normativa e cronologia','Grave','La posizione è dichiarata già determinata alla pubblicazione, mentre la stessa frase richiede maturazione entro la scadenza.','Ammettere condizioni che maturano entro il termine; costruire un esempio datato. Correggere anche l’affermazione che a 22–23 anni non si possano completare 12 mesi di servizio prima dei 25.')
add('SP02/02',137,'Requisiti','Grave','La riga più di 26 anni presenta il volontariato come via generica, omettendo limite massimo e possibile elevazione per servizio militare.','Esporre il limite 37 per volontari iscritti da almeno un anno e l’elevazione per servizio militare fino a tre anni, con distinta riserva. Non confondere ammissione e 35% riservato. Bando art.2, PDF locale pp.5–6; E04.')
add('SP02/02',71,'Riserve','Medio','Il 95% riservato è presentato come minimo garantito e il residuo come bacino sostanziale dei civili.','Distinguere posti nominalmente riservati, merito, requisiti delle categorie e devoluzione delle riserve non coperte; evitare inferenze sulle probabilità individuali. Inserire un esempio di graduatoria compatibile con la disciplina del bando.')
add('SP02/02',211,'Normativa','Grave','Qualità morali e condotta sono ridotte alla presenza di una condanna irrevocabile per delitto non colposo.','Distinguere condotta ex art.26 dalle specifiche cause elencate dal bando; includere misure di prevenzione e altre esclusioni pertinenti. Correggere anche il riepilogo; E04, art.2.')
add('SP02/02',233,'Tabella e precisione','Medio','Valori di forza e composizione corporea sono riportati senza operatori e unità completi; la visita da 40 euro appare come costo certo.','Inserire ≥, kg e percentuali pertinenti, tolleranze e fonte; dichiarare il costo puramente illustrativo o eliminarlo. Chiarire che la valutazione è della commissione competente.')
add('SP02/03',121,'Errore matematico','Grave','Si sostiene che una penalità renda sempre negativa l’aspettativa di una risposta casuale.','Usare E=pG−(1−p)P e confronto con omissione. Con quattro opzioni, +1/−0,1 e omissione zero, E=0,175: il controesempio smentisce la frase. Calcolare soglia p>P/(G+P), adattata a eventuale penalità dell’omissione.')
add('SP02/03',91,'Inferenza non fondata','Medio','Procedure automatizzate diventano necessariamente lettura ottica cartacea; l’elenco delle tipologie diventa ordine obbligatorio delle domande.','Separare quanto dice il bando da modalità affidate all’avviso. La stessa cautela vale per l’interfaccia ipotizzata in SP04/03. Aggiornare l’avviso successivo al 15 settembre prima della pubblicazione.')
add('SP02/03',139,'Coerenza didattica','Medio','Non studiare il perché, nessun altro manuale utile e soli quesiti scientifici utili al mestiere sono assoluti non dimostrati e contraddicono SP02/08.','Distinguere profondità necessaria al filtro e comprensione minima, preservare logica/informatica/inglese; prevedere manutenzione della preselettiva dopo la soglia. Simulazioni provvisorie a tempo devono essere etichettate, non vietate fino all’avviso.')
add('SP02/04',155,'Protocollo fisico','Grave','La sbarra viene regolata all’altezza delle dita con braccia lungo i fianchi: il protocollo richiede braccia in alto per la regolazione, poi lungo i fianchi alla partenza.','Separare le due posizioni e riportare il corretto ordine; Allegato A ufficiale, PDF locale p.6. Il difetto altera concretamente l’esercizio.')
add('SP02/04',241,'Punteggio','Grave','Il modulo peggiore è indicato come punteggio della Prova 1.','Scrivere media aritmetica dei tre moduli, purché ognuno raggiunga 21/30. Il peggiore è un vincolo di ammissione e una priorità di preparazione. Correggere anche sintesi e spiegazioni; Allegato A pp.1–2.')
add('SP02/04',324,'Quiz e casi','Grave','Quiz 1 e domanda aperta 1 attribuiscono 28 alla trave, che ammette 30/25/21. Aperta 3 non specifica sesso; aperta 7 chiede guadagno in punti da 20 secondi senza tabella sufficiente.','Usare punteggi realizzabili, specificare categoria e fornire tabella completa o restringere la domanda. Ricalcolare le soluzioni: 5 minuti e 10 secondi non hanno lo stesso esito nelle due soglie di corsa.')
add('SP02/04',353,'Quiz e strategia','Medio','Il confronto fra gradienti di esercizi non prova quale investimento convenga al candidato; quiz 6 ha alternative sovrapposte.','Confrontare il margine iniziale, la trasformazione in punti e il peso del modulo nella media. Riscrivere quiz 6 con opzioni reciprocamente esclusive, distinguendo esclusione e posto in graduatoria.')
add('SP02/04',179,'Tutela e protocollo','Medio','Cronometraggio elettronico è presentato come privo di contestabilità; ordine corsa dopo trazioni è dato per necessario pur spettando alla commissione.','Eliminare l’assoluto sulla tutela; distinguere procedura immediata di riesame e rimedi generali. Presentare un ordine di allenamento come ipotesi, non vincolo del concorso; verificare certificazione sportiva senza imporre universalmente ECG sotto sforzo.')
add('SP02/04',259,'Coerenza e titoli','Medio','Conseguire una patente in sei mesi viene confrontato con la piscina senza fissare il termine utile dei titoli; seguono affermazioni di risultato non aleatorio.','Esplicitare possesso entro scadenza e tempo residuo; prima soglie/idoneità, poi incremento di punteggio. Eliminare garanzie di risultato e distinguere prestazione preparata da esito certo.')
add('SP02/05',116,'Completezza per profilo','Medio','La mappa direttiva non rende operativa l’orientazione alla prevenzione incendi richiesta dalla decisione di perimetro D2.','Aggiungere una breve mappa funzioni/fonti/processi con rinvii, proporzionata a un manuale strategico. Confermati sul PDF ordinario titoli a parità e un’unica prova scritta: non sono errori da correggere.')
add('SP02/06',89,'Rinvii','Medio','Si prescrivono destinazioni precise, ma la tabella rinvia ad aree del volume base senza capitoli o sezioni verificabili.','Sostituire aree con codice, titolo e sezione; chiarire che il controllo formale non impone di sospendere ogni preparazione fisica o linguistica parallela.')
add('SP02/07',151,'Pianificazione','Medio','Obiettivo trenta risposte orali al mese e cinque a settimana non coincidono; titolo 30/60/90 privo delle due varianti più brevi.','Allineare il target e fornire varianti con presupposti dichiarati oppure titolo ciclo di 90 giorni. Conservare l’avvertenza già presente di non allenare l’apnea da soli.')
add('SP02/08',143,'Casi','Medio','Sono promessi due casi completi, ma Andrea non ha punteggi/margini e Francesca non produce un elaborato o esito valutabile.','Completare entrambi con dati e output: punteggi per modulo e priorità motivate; traccia tecnica, scaletta e rubriche di valutazione. Evitare una nuova ripetizione del controllo del bando.')
add('SP03/01',67,'Giurisdizione','Grave','La magistratura ordinaria viene associata indistintamente a controversie amministrative.','Specificare giurisdizione civile e penale e casi di tutela/questioni incidentali previsti dalla legge; distinguere i giudici amministrativi, esclusi dal perimetro professionale del modulo.')
add('SP03/01',147,'Fonti e residui editoriali','Medio','Il lettore incontra limiti del file acquisito dell’art.5 e ricostruzioni della ricerca, anziché una spiegazione consolidata.','Spostare il resoconto documentale nella source; nel libro indicare norma, requisito e limite interpretativo realmente utile. Analogo SP03/03: non dedurre l’origine del limite d’età dal solo art.1 della L.1035/1966.')
add('SP03/02',103,'Completezza normativa','Medio','Il minimo 6/10 in ogni materia orale non esplicita l’eccezione della lingua, valutata per sufficienza; la soglia complessiva non viene resa operativa.','Precisare giudizio di sufficienza per lingua e totale minimo 108 nelle due prove; inserire esempio con insufficienza non compensabile. Bando 450, art.8, PDF locale p.10.')
add('SP03/02',225,'Cronologia dei casi','Medio','La scelta di candidarsi a novembre 2025 utilizza un diario noto soltanto nel febbraio 2026.','Separare decisione entro termine e successivo aggiornamento del piano. Anche il confronto di Elena in SP03/06 agosto 2025 deve essere dichiarato esempio composito se usa bandi di ottobre/dicembre successivi.')
add('SP03/03',59,'Precisione normativa','Medio','Non superato e non compiuti sono alternati senza spiegare computo, fonte e benefici. Non è stato accertato che producano esiti diversi nel caso presentato.','Usare formula del bando, citare D.P.C.M.141/2000 richiamato nel preambolo e aggiungere esempio sul compleanno/scadenza con verifica giuridica. Non classificare come errore certo l’equivalenza fra le due espressioni senza ulteriore riscontro.')
add('SP03/04',133,'Caso impossibile','Grave','Marta inizia la pratica nel luglio 2024, si laurea nel dicembre 2024 e avrebbe già cinque precedenti partecipazioni notarili: mancano condizioni che rendano possibile l’accesso a quei concorsi.','Separare caso durata pratica e caso conteggio inidoneità, oppure anticipare di anni laurea/pratica e precisare gli episodi. Dichiarare quali esiti contano e quali no.')
add('SP03/04',202,'Termine requisito','Grave','La pratica è richiesta già al momento della domanda, mentre altrove e nel bando è entro il termine utile di presentazione.','Uniformare alla scadenza, distinguendo invio anticipato, maturazione del requisito e certificazione successiva. Bando notarile artt.2–3, PDF GU locale pp.7–8.')
add('SP03/05',305,'Didattica professionale','Medio','Tre tracce concrete sono seguite quasi solo da identificazione del formato; manca un output giuridico che mostri il metodo promesso.','Aggiungere tesi motivata sulla responsabilità precontrattuale, soluzione della controversia Beta e clausola notarile esemplificativa con presupposti. Affiancare un prima/dopo breve: in SP03/07 esiste già un microesempio, ma non risolve queste tracce.')
add('SP03/05',136,'Metodo','Medio','Tesi e obiezioni vengono imposte a ogni tema; la presenza di effetti negoziali rischia di determinare da sola il formato.','Fare prevalere verbo della consegna e compito richiesto; distinguere tema illustrativo, soluzione pratica e redazione di atto.')
add('SP03/06',155,'Errore di formulazione','Medio','Una pagina corretta male insegna più di trenta lette ribalta il senso didattico.','Scrivere una pagina scritta male e corretta bene; uniformare gli imperativi aggiungi in SP03/02 e classificale in SP03/07.')
add('SP03/06',71,'Promessa del piano','Medio','Il piano pluriennale resta un insieme di quattro trimestri vuoti e istruzioni, senza esempio di percorso su più anni.','Aggiungere un esempio condizionato di anno 1/anno 2 con produzione, revisione, ripasso e criteri di riesame; nessuna promessa di durata universale o superamento.')
add('SP03/07',174,'Didattica e coerenza','Medio','Richiamare organo legale dello Stato nell’introduzione non mostra come correggere la mancata applicazione giuridica al caso.','Mostrare una tesi, un’eccezione e il relativo presupposto fattuale; distinguere fonti mancanti da dubbio interpretativo nel semaforo. Non trasformare formule istituzionali in preamboli obbligatori.')
add('SP04/01',102,'Tentativi','Grave','La frase un tentativo consuma una delle quattro occasioni amplia indebitamente la regola corretta esposta due righe prima.','Precisare quattro serie complete di scritti non superate; non ogni presenza o insuccesso all’orale. Uniformare SP04/06 r.173 e SP04/07. Il rinvio del capitolo all’art.2 c.3 è corretto: correggere invece art.4 c.3 nella source. E05.')
add('SP04/01',90,'Logica decisionale','Medio','I requisiti di ammissione entrano in uno scoring compensabile 0–3 per scegliere la carriera.','Anteporre ammissibilità come condizione necessaria; usare punteggi soltanto per preferenze e preparazione fra alternative ammissibili.')
add('SP04/02',67,'Caso e requisito','Grave','Paolo compie 36 anni prima della scadenza e ha un solo figlio; il caso suggerisce una finestra aperta, ma l’unica elevazione indicata porta il limite a 36, già superati.','Usare date precise e concludere fuori termine in assenza di altri benefici, oppure farlo ancora trentacinquenne. Bando 158, art.2, PDF locale p.3.')
add('SP04/02',89,'Calcolo e didattica','Medio','La strategia sul punteggio asimmetrico resta verbale e contraddice il successivo invito a ignorare i valori durante la prova.','Confrontare risposta con omissione: soglie di probabilità 2/9 facile, 1/5 media, 4/23 difficile. Distinguere valore del quesito dal totale provvisorio; applicabilità subordinata a conoscere la classe di difficoltà.')
add('SP04/02',105,'Modalità della prova','Medio','La trattazione degli scritti prefettizi omette la modalità digitale, mentre il confronto enfatizza quella diplomatica.','Aggiungere modalità digitale del bando art.10 e un esercizio di gestione digitale dell’elaborato; preservare la distinzione sui materiali consentiti. E06 e PDF locale p.11.')
add('SP04/02',166,'Normativa organizzativa','Grave','La formazione è attribuita alla SSAI come ente ancora operativo, senza raccordo con la soppressione del 2014.','Aggiornare all’art.21 D.L.90/2014 e alle funzioni trasferite alla SNA; distinguere denominazione storica, sede didattica e organizzazione attuale. E07.')
add('SP04/02',47,'Completezza punteggio','Medio','La formula del risultato finale lascia fuori i titoli e il bonus della lingua facoltativa.','Mostrare formula completa e un esempio conforme agli artt.13–14: base delle prove, punteggi aggiuntivi e preferenze distinti. Non confondere punteggio aggiuntivo con criterio di parità.')
add('SP04/03',51,'Titolo di accesso','Grave','La richiesta di una specifica classe di laurea non recepisce l’ampliamento del bando diplomatico 2026.','Allineare al requisito laurea magistrale o titolo equiparato e al regime dei titoli esteri; E05 art.2.')
add('SP04/03',151,'Programma','Grave','La descrizione economica non restituisce il programma diplomatico 2026.','Allineare economia politica, politica economica, economia internazionale e finanziaria e commercio internazionale; coordinare SP04/01 e 05. E05 artt.7 e 9.')
add('SP04/03',183,'Omissione strategica','Grave','Manca la nuova materia orale facoltativa, distinta dalle lingue.','Integrare scelta in domanda, cinque opzioni, soglia e bonus; raccordare Decoder, piano e graduatoria. E05 art.11: sufficienza 1,2, massimo 2 centesimi.')
add('SP04/03',183,'Graduatoria','Medio','Manca una formula complessiva che renda utilizzabili le componenti facoltative e i titoli.','Inserire media scritti + orale + bonus facoltativi + titoli, con limiti e condizioni; E05 artt.8,12,13. Non duplicare tutte le regole in ogni capitolo.')
add('SP04/04',131,'Scelta vincolata','Grave','Cambiare lingua dopo otto settimane viene consigliato senza considerare la scelta già dichiarata e i termini della domanda.','Collocare la diagnosi prima dell’opzione; dopo la scadenza ammettere modifiche soltanto se consentite. E05 art.3; verificare separatamente la procedura prefettizia.')
add('SP04/04',143,'Apparato didattico','Medio','Il metodo linguistico è descritto senza un esempio completo in lingua o una traduzione commentata.','Aggiungere un breve testo, consegna, risposta e correzione per un formato; esempio parallelo di conversazione. Il volume rimane strategico, senza diventare un corso linguistico.')
add('SP04/05',135,'Metodo di simulazione','Medio','Leggere le istruzioni informatiche una sola volta è un vincolo arbitrario che allena memoria e può peggiorare il controllo della consegna.','Consentire rilettura salvo specifico protocollo; misurare comprensione, esecuzione e verifica. Aggiungere un dossier orale risolto con risposta completa, non solo istruzioni di costruzione.')
add('SP04/06',97,'Promessa del piano','Medio','Il percorso 6–12 mesi non presenta una settimana compilata né ripartizioni esemplificative controllabili.','Inserire settimane da 12/20 ore con ipotesi esplicite e due percorsi per profilo, checkpoint e carico linguistico; sostituire retromarcia con pianificazione a ritroso.')
add('SP04/07',25,'Residui di produzione','Medio','Accorpamento motivato, cinque nuclei sopra soglia e riferimenti alle pagine editoriali sono istruzioni staff visibili nel testo; compare persino il residuo sugli elenchi diagnostici.','Rimuovere dal testo pubblico e conservare nei materiali di produzione. Analogo SP01/05–06 apertura editoriale, SP01/08 regole editoriali, SP02/06 controllo preconsegna e SP02/08 elenchi diagnostici.')
add('SP02/01',179,'Quiz trasversali','Medio','Molti commenti sono formule generiche non pertinenti alle singole alternative; SP02/07–08 e SP04/07 hanno tutte le chiavi B.','Riscrivere commenti uno per uno e distrattori plausibili; ricollocare opzioni solo dopo validazione. Non rilevato il pattern sistematico chiave D/commento D errata osservato in altri volumi.')
add('SP01/06',26,'Lingua e ripetizioni','Lieve','Doppio binario ripetuto a r.26/34; nel usare ricorre qui e in SP01/08. Altri refusi sono disseminati.','Correggere nell’usare; SP02/03 undici parole (citazione di sedici) e diecimila-per-mille; SP02/07 questo triage; SP04/03 estrai; SP04/04 non tentare; SP04/05 distingui/offri/riparti; SP04/07 segui; SP01/10 scadenza scaduta.')
